-- Generated by scripts/generate-session-turns-schema.mjs.
-- Read-only activation check: bind hour-aligned UTC verifyFrom/verifyTo inside the backfilled,
-- retained range. Any row with differs = 1 blocks SESSION_TURNS_READ_FROM.
SELECT throwIf({verifyTo:DateTime('UTC')} <= {verifyFrom:DateTime('UTC')}
  OR toStartOfHour({verifyFrom:DateTime('UTC')}) != {verifyFrom:DateTime('UTC')} OR toStartOfHour({verifyTo:DateTime('UTC')}) != {verifyTo:DateTime('UTC')},
  'Session turns verification requires a positive hour-aligned UTC window');

SELECT Client, Kind, t.keys AS table_keys, r.keys AS raw_keys, table_keys != raw_keys AS differs
FROM (
  SELECT Client, Kind, uniqExactMerge(Keys) AS keys
  FROM claude_code.session_turns_v1
  WHERE hour >= {verifyFrom:DateTime('UTC')} AND hour < {verifyTo:DateTime('UTC')}
  GROUP BY Client, Kind
) AS t
FULL OUTER JOIN (
  SELECT Client, Kind, uniqExact(cityHash64(Key)) AS keys
  FROM (
  SELECT toStartOfHour(toDateTime(Timestamp, 'UTC')) AS hour,
    multiIf(EventName = 'codex.user_prompt', 'codex', 'claude') AS Client,
    if(EventName = 'codex.user_prompt', LogAttributes['conversation.id'], SessionId) AS Sid,
    coalesce(nullIf(ResourceAttributes['user.email'], ''),
      nullIf(ResourceAttributes['enduser.id'], ''), '') AS UserIdentity,
    if(EventName IN ('api_request', 'claude_code.api_request'), 'request', 'turn') AS Kind,
    if(EventName IN ('api_request', 'claude_code.api_request'), LogAttributes['model'], '') AS Mdl,
    multiIf(EventName IN ('user_prompt', 'claude_code.user_prompt'), multiIf(PromptId != '', concat('p:', PromptId), LogAttributes['event.sequence'] != '', concat('s:', LogAttributes['event.sequence'], ':', toString(Timestamp)), concat('r:', toString(Timestamp), ':', toString(cityHash64(toString(mapSort(LogAttributes)))))),
      EventName IN ('api_request', 'claude_code.api_request'), if(LogAttributes['event.sequence'] != '', concat('s:', LogAttributes['event.sequence'], ':', toString(Timestamp)), concat('r:', toString(Timestamp), ':', toString(cityHash64(toString(mapSort(LogAttributes)))))),
      concat(toString(Timestamp), toString(mapSort(ResourceAttributes)), toString(mapSort(LogAttributes)))) AS Key
  FROM claude_code.otel_logs
  WHERE (EventName IN ('user_prompt', 'claude_code.user_prompt') OR EventName IN ('api_request', 'claude_code.api_request') OR EventName = 'codex.user_prompt') AND (Timestamp >= {verifyFrom:DateTime('UTC')} AND Timestamp < {verifyTo:DateTime('UTC')})
  )
  WHERE Sid != ''
  GROUP BY Client, Kind
) AS r USING (Client, Kind)
ORDER BY Client, Kind;
